    --border: #331111;
    --input: #331111;
    --ring: #ff3333;
    --radius: 0.375rem;

    --font-orbitron: 'Orbitron', 'Share Tech Mono', ui-monospace, monospace;
    --font-share-tech-mono: 'Share Tech Mono', ui-monospace, monospace;
    --font-sans: 'Inter', ui-sans-serif, system-ui, sans-serif;
    --font-display: 'Outfit', ui-sans-serif, system-ui, sans-serif;
    --font-mono: 'JetBrains Mono', 'Share Tech Mono', ui-monospace, SFMono-Regular, monospace;
    --color-bg-primary: #000000;
    --color-text-primary: #e0e0e0;
    --color-accent-red: #ff3333;
