  html, 
  body {
    direction: ltr !important;
    text-align: left;
    unicode-bidi: normal;
    background-color: #000000;
    color: #e0e0e0;
    font-family: var(--font-sans);
    min-height: 100vh;
    overflow-x: hidden;
  }

  input, 
  textarea, 
  select {
    direction: ltr !important;
    text-align: left !important;
    unicode-bidi: normal !important;
  }
}

@layer components {
  /* ==========================================================================
     Dalek Form Controls
     ========================================================================== */
  .dalek-input {
    direction: ltr !important;
    text-align: left !important;
    unicode-bidi: normal !important;
    background: rgba(10, 10, 10, 0.9);
    color: #f0f0f0;
    border: 1px solid var(--color-border-dark, #331111);
    border-radius: 4px;
    font-family: var(--font-share-tech-mono), monospace;
    outline: none;
    will-change: border-color, box-shadow;
    transition: border-color 0.15s cubic-bezier(0.4, 0, 0.2, 1), box-shadow 0.15s cubic-bezier(0.4, 0, 0.2, 1);
  }

  .dalek-input:focus {
    border-color: var(--color-accent-red, #ff3333);
    box-shadow: 0 0 8px rgba(255, 32, 32, 0.2);
  }

  .dalek-btn {
    background: rgba(20, 20, 20, 0.85);
    border: 1px solid var(--color-border-dark, #331111);
    color: #d0d0d0;
    border-radius: 4px;
    font-family: var(--font-orbitron), sans-serif;
    cursor: pointer;
    will-change: background-color, border-color, color, box-shadow;
    transition: background-color 0.15s cubic-bezier(0.4, 0, 0.2, 1), border-color 0.15s cubic-bezier(0.4, 0, 0.2, 1), color 0.15s cubic-bezier(0.4, 0, 0.2, 1), box-shadow 0.15s cubic-bezier(0.4, 0, 0.2, 1);
  }

  .dalek-btn:hover {
    background: rgba(35, 15, 15, 0.95);
    border-color: var(--color-accent-red, #ff3333);
    color: #ffffff;
  }

  .dalek-btn-primary {
    background: rgba(180, 20, 20, 0.85);
    border-color: var(--color-accent-red, #ff3333);
    color: #ffffff;
  }

  .dalek-btn-primary:hover {
    background: rgba(220, 30, 30, 0.95);
    box-shadow: 0 0 10px rgba(255, 32, 32, 0.4);
  }

  /* ==========================================================================
     Custom Cyber/Dalek Scrollbars
     ========================================================================== */
  .dalek-scrollbar {
    scrollbar-width: thin;
    scrollbar-color: #331111 #080000;
  }

  .dalek-scrollbar::-webkit-scrollbar {
    width: 6px;
    height: 6px;
  }

  .dalek-scrollbar::-webkit-scrollbar-track {
    background: #080000;
  }

  .dalek-scrollbar::-webkit-scrollbar-thumb {
    background: #331111;
    border-radius: 3px;
  }

  .dalek-scrollbar::-webkit-scrollbar-thumb:hover {
    background: #ff2020;
  }

  .no-scrollbar {
    -ms-overflow-style: none;
    scrollbar-width: none;
  }

  .no-scrollbar::-webkit-scrollbar {
    display: none;
  }

